function isLicenseFilename(name: string): boolean {
	const normalized = name.toLowerCase();
	return (
		normalized === 'license' ||
		normalized === 'licence' ||
		normalized.startsWith('license.') ||
		normalized.startsWith('licence.')
	);
}

